    'faq_q10_answer' => '<strong>Anton Barinov</strong>, a PHP developer.',
    'faq_q2' => '<strong>Is it a CRM or a εργασία manager?</strong><br>Both. A CRM for clients and counterparties, a εργασία manager for εργασίες, plus έργο management, chat, ημερολόγιο, and AI.',
    'faq_q3' => '<strong>Is it suitable for freelancers?</strong><br>Yes. There is no minimum ομάδα size. A single χρήστης gets CRM, εργασίες, an AI day plan, and chat without per-seat fees.',
    'faq_q4' => '<strong>Does it work on shared hosting?</strong><br>Yes. PHP 8.1+ and MySQL are enough. The browser installer configures everything.',
    'faq_q5' => '<strong>Are there limits on χρήστες and εργασίες?</strong><br>No. Unlimited χρήστες, εργασίες, έργα, and clients. The only limitation is server capacity.',
    'faq_q6' => '<strong>Where is the δεδομένα stored?</strong><br>100% on your server. The system never syncs δεδομένα to the cloud.',
    'faq_q7' => '<strong>What AI tools are διαθέσιμο?</strong><br>20+ tools: idea exploration, day/εβδομάδα plans, summaries, checklists, risks, meeting preparation.',
